function solve(s) {
  let cur = s;
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i + 1 < cur.length; i++) {
      if (cur[i] === cur[i + 1]) {
        cur = cur.slice(0, i) + cur.slice(i + 2);
        changed = true;
        break;
      }
    }
  }
  return cur;
}

function solve(s) {
  const st = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (st.length > 0 && st[st.length - 1] === ch) {
      st.pop();
    } else {
      st.push(ch);
    }
  }
  return st.join('');
}
